document.getElementById('check').onclick=async()=>{const out=document.getElementById('result');if(!window.isSecureContext){out.textContent='Abre el enlace HTTPS del visor.';return;}if(!navigator.xr){out.textContent='WebXR no está disponible. Usa Chrome y actualiza Servicios de Google Play para RA.';return;}try{const ok=await navigator.xr.isSessionSupported('immersive-ar');out.textContent=ok?'El navegador admite AR. Abre el modelo y pulsa Ver en AR para probar la cámara y detectar una superficie.':'AR no está disponible en esta configuración. Revisa Chrome y Servicios de Google Play para RA.';}catch{out.textContent='No se pudo comprobar AR. Vuelve a abrir el enlace en Chrome.';}};
